import math, collections

WIN = 900  # 15 min window of samples

class LagMonitor:
    def __init__(self, targets):
        self.win = collections.defaultdict(collections.deque)  # (tenant, source) -> deque[(t, lag)]
        self.last_event = {}
        self.over = collections.defaultdict(int)               # consecutive minutes over 2x target
        self.targets = targets

    def record_change(self, tenant, source, modified_at, indexed_at, now):
        lag = max(0.0, indexed_at - modified_at)
        self.win[(tenant, source)].append((now, lag))
        self.last_event[(tenant, source)] = now

    def tick(self, now):
        alerts = []
        for key, dq in self.win.items():
            while dq and dq[0][0] < now - WIN:
                dq.popleft()
            target = self.targets[key]
            if not dq:
                # Tricky part: no samples is not zero lag. Silence past 2x target is itself an alert.
                if now - self.last_event.get(key, 0) > 2 * target:
                    alerts.append(Alert(key, None, target, "silent"))
                continue
            lags = sorted(l for _, l in dq)
            p95 = lags[math.ceil(0.95 * len(lags)) - 1]
            self.over[key] = self.over[key] + 1 if p95 > 2 * target else 0
            if self.over[key] >= 5:
                alerts.append(Alert(key, p95, target, p95 / target))
        return alerts

