SLO = 0.99

def burn(buckets, now, secs):
    ok = err = 0
    for ts, o, e in buckets:
        if ts >= now - secs:
            ok += o; err += e
    n = ok + err
    return (err / n) / (1 - SLO) if n else 0.0, n

def on_outcome(b, now, status, retry_after):
    # Tricky part: a 429 or a 5xx with Retry-After is the source asking us to slow down, not a failure.
    if status == 429 or (status >= 500 and retry_after):
        b.pause_until = now + (retry_after or 60)
        return
    minute = int(now // 60) * 60
    b.add(minute, ok=status < 400, err=status >= 400)

def evaluate(b, now):
    r5, n5 = burn(b.buckets, now, 300)
    if b.state == "closed" and r5 > 10 and n5 >= 20:
        b.state = "open"; pause_workflow(b.key); open_repair_task(b.key, b.last_error)
    elif b.state == "open" and now - b.since > b.cool_s:
        b.state = "half_open"; b.probe_ok = 0
    elif b.state == "half_open":
        if b.last_probe_ok:
            b.probe_ok += 1
            if b.probe_ok >= 3:
                b.state = "closed"; resume_workflow(b.key)
        else:
            b.state = "open"
    return b.state

