def check(db, app, path, now):
    lo = max(FLOOR, db.quantile(app, path, now.hour, now.weekday(), q=0.05, weeks=4))
    last = db.counts(app, path, last=2)
    if len(last) == 2 and all(c < lo for c in last) and not in_maintenance(app, now):
        request_sweep(app, path); return "stalled"
    return "quiet" if last and last[-1] < lo else "ok"
